#include "core/UiDocument.h"

#include <filesystem>
#include <fstream>
#include <sstream>

#include <gtest/gtest.h>

using namespace kevc::ui;

namespace {

// Written the way Glade and Cambalache write them, with the odd bits a hand-edited file has.
const std::string kWindow = R"(<?xml version="1.0" encoding="UTF-8"?>
<!-- Generated by hand -->
<interface domain="demo">
  <requires lib="gtk" version="4.0"/>
  <object class="GtkApplicationWindow" id="main_window">
    <property name="title" translatable="yes">Demo &amp; more</property>
    <property name="default-width">640</property>
    <property name="default_height">480</property>
    <child type="titlebar">
      <object class="GtkHeaderBar" id="header">
        <child type="end">
          <object class="GtkMenuButton">
            <property name="icon-name">open-menu-symbolic</property>
          </object>
        </child>
      </object>
    </child>
    <child>
      <object class="GtkBox" id="content">
        <property name="orientation">vertical</property>
        <property name='spacing' >6</property>
        <child>
          <object class="GtkLabel" id="greeting">
            <property name="label"><![CDATA[Hello <b>world</b>]]></property>
          </object>
        </child>
        <child>
          <object class="GtkButton" id="save">
            <property name="label">_Save</property>
            <property name="action-name">win.save</property>
            <signal name="clicked" handler="on_save_clicked" swapped="no"/>
            <child>
              <object class="GtkShortcutController">
                <property name="scope">global</property>
              </object>
            </child>
          </object>
        </child>
        <child>
          <object class="AdwStatusPage" id="status">
            <property name="title">Nothing here</property>
            <property name="child">
              <object class="GtkButton" id="retry"/>
            </property>
          </object>
        </child>
        <child>
          <object class="GtkEntry" id="empty_entry"/>
        </child>
      </object>
    </child>
  </object>
</interface>
)";

ClassKind kindOf(const std::string& cls) {
    if (cls == "GtkApplicationWindow" || cls == "GtkWindow" || cls == "GtkDialog") return ClassKind::Window;
    if (cls == "GtkShortcutController" || cls == "GtkGestureClick") return ClassKind::Controller;
    if (cls == "GtkAdjustment" || cls == "GtkStringList") return ClassKind::Other;
    if (cls.rfind("Gtk", 0) == 0) return ClassKind::Widget;
    return ClassKind::Unknown;
}

Node* byId(UiDocument& doc, const std::string& id) {
    for (Node* o : doc.objects())
        if (UiDocument::objectId(*o) == id) return o;
    return nullptr;
}

// The lines of `after` that differ from `before` (same line count assumed when `sameCount`).
std::vector<std::string> lines(const std::string& text) {
    std::vector<std::string> out;
    std::istringstream in(text);
    for (std::string line; std::getline(in, line);) out.push_back(line);
    return out;
}

} // namespace

TEST(UiDocument, WritesBackExactlyWhatItRead) {
    auto doc = UiDocument::parse(kWindow);
    EXPECT_EQ(doc.text(), kWindow);
    const std::string odd = "<interface>\r\n\t<object class='GtkLabel' id = \"a\" ><property name=\"label\">x &lt; y &#x263A;</property></object>  \n</interface>";
    EXPECT_EQ(UiDocument::parse(odd).text(), odd);
}

TEST(UiDocument, ReadsObjectsAndProperties) {
    auto doc = UiDocument::parse(kWindow);
    const auto top = doc.topLevelObjects();
    ASSERT_EQ(top.size(), 1u);
    EXPECT_EQ(UiDocument::className(*top[0]), "GtkApplicationWindow");
    EXPECT_EQ(UiDocument::property(*top[0], "title"), "Demo & more");
    EXPECT_EQ(UiDocument::property(*top[0], "default-height"), "480"); // written default_height
    EXPECT_FALSE(UiDocument::property(*top[0], "resizable"));

    const auto kids = UiDocument::childObjects(*top[0]);
    ASSERT_EQ(kids.size(), 2u);
    EXPECT_EQ(UiDocument::objectId(*kids[0]), "header");
    EXPECT_EQ(UiDocument::objectId(*kids[1]), "content");
    Node* status = byId(doc, "status");
    ASSERT_TRUE(status);
    ASSERT_EQ(UiDocument::childObjects(*status).size(), 1u); // via <property name="child">
    EXPECT_EQ(UiDocument::parentObject(*UiDocument::childObjects(*status)[0]), status);
    EXPECT_EQ(UiDocument::parentObject(*top[0]), nullptr);

    EXPECT_EQ(UiDocument::property(*byId(doc, "greeting"), "label"), "Hello <b>world</b>");
    EXPECT_EQ(UiDocument::property(*byId(doc, "content"), "spacing"), "6");
    EXPECT_EQ(doc.objects().size(), 10u);
    EXPECT_EQ(doc.find(status->uid), status);
}

TEST(UiDocument, EditingAPropertyChangesOnlyItsLine) {
    auto doc = UiDocument::parse(kWindow);
    doc.setProperty(*byId(doc, "content"), "spacing", "12");
    doc.setProperty(*doc.topLevelObjects()[0], "title", "Fish & <Chips>");
    const auto before = lines(kWindow), after = lines(doc.text());
    ASSERT_EQ(before.size(), after.size());
    std::vector<std::string> changed;
    for (size_t i = 0; i < before.size(); ++i)
        if (before[i] != after[i]) changed.push_back(after[i]);
    ASSERT_EQ(changed.size(), 2u);
    EXPECT_EQ(changed[0], "    <property name=\"title\" translatable=\"yes\">Fish &amp; &lt;Chips&gt;</property>");
    EXPECT_EQ(changed[1], "        <property name='spacing' >12</property>");

    // Setting the value it already has changes nothing.
    auto same = UiDocument::parse(kWindow);
    same.setProperty(*byId(same, "content"), "spacing", "6");
    EXPECT_EQ(same.text(), kWindow);
}

TEST(UiDocument, NewPropertiesGoAfterTheOthersIndentedLikeThem) {
    auto doc = UiDocument::parse(kWindow);
    doc.setProperty(*byId(doc, "content"), "margin-top", "8");
    const auto out = doc.text();
    EXPECT_NE(out.find("        <property name='spacing' >6</property>\n"
                       "        <property name=\"margin-top\">8</property>\n"
                       "        <child>\n"),
              std::string::npos)
        << out;

    // An object with no properties: the new one goes before its children.
    doc.setProperty(*byId(doc, "header"), "show-title-buttons", "False");
    EXPECT_NE(doc.text().find("<object class=\"GtkHeaderBar\" id=\"header\">\n"
                              "        <property name=\"show-title-buttons\">False</property>\n"
                              "        <child type=\"end\">"),
              std::string::npos);

    // An empty element <object …/> opens up.
    doc.setProperty(*byId(doc, "empty_entry"), "placeholder-text", "Name");
    EXPECT_NE(doc.text().find("          <object class=\"GtkEntry\" id=\"empty_entry\">\n"
                              "            <property name=\"placeholder-text\">Name</property>\n"
                              "          </object>\n"),
              std::string::npos)
        << doc.text();
}

TEST(UiDocument, RemovingAPropertyRemovesItsLine) {
    auto doc = UiDocument::parse(kWindow);
    doc.removeProperty(*doc.topLevelObjects()[0], "default-width");
    auto expected = kWindow;
    const std::string line = "    <property name=\"default-width\">640</property>\n";
    expected.erase(expected.find(line), line.size());
    EXPECT_EQ(doc.text(), expected);

    // The last thing inside an element: it closes up.
    doc.removeProperty(*byId(doc, "greeting"), "label");
    EXPECT_NE(doc.text().find("<object class=\"GtkLabel\" id=\"greeting\"></object>"), std::string::npos);
}

TEST(UiDocument, InsertsNestedElementsLaidOut) {
    auto doc = UiDocument::parse(kWindow);
    Node* box = byId(doc, "content");
    Node* child = doc.insertElement(*box, R"(<child><object class="GtkSwitch" id="sw"><property name="active">True</property></object></child>)", 2); // after the 2 properties
    ASSERT_TRUE(child);
    EXPECT_EQ(child->parent, box);
    const auto out = doc.text();
    EXPECT_NE(out.find("        <property name='spacing' >6</property>\n"
                       "        <child>\n"
                       "          <object class=\"GtkSwitch\" id=\"sw\">\n"
                       "            <property name=\"active\">True</property>\n"
                       "          </object>\n"
                       "        </child>\n"
                       "        <child>\n"
                       "          <object class=\"GtkLabel\" id=\"greeting\">"),
              std::string::npos)
        << out;
    EXPECT_EQ(UiDocument::childObjects(*box).size(), 5u);
    EXPECT_EQ(UiDocument::objectId(*UiDocument::childObjects(*box)[0]), "sw");
    // Everything else is untouched; parsing the result again gives the same text.
    EXPECT_EQ(UiDocument::parse(out).text(), out);

    doc.removeElement(*child);
    EXPECT_EQ(doc.text(), kWindow);
}

TEST(UiDocument, CompactFilesStayCompact) {
    auto doc = UiDocument::parse(R"(<interface><object class="GtkBox" id="b"><child><object class="GtkLabel"/></child></object></interface>)");
    Node* box = doc.topLevelObjects()[0];
    doc.insertElement(*box, "<child>\n  <object class=\"GtkButton\"/>\n</child>");
    EXPECT_EQ(doc.text(), R"(<interface><object class="GtkBox" id="b"><child><object class="GtkLabel"/></child><child><object class="GtkButton"/></child></object></interface>)");
}

TEST(UiDocument, EditsAttributes) {
    auto doc = UiDocument::parse(kWindow);
    Node* entry = byId(doc, "empty_entry");
    doc.setAttribute(*entry, "id", "name_entry");
    EXPECT_NE(doc.text().find("          <object class=\"GtkEntry\" id=\"name_entry\"/>\n"), std::string::npos);
    doc.setAttribute(*entry, "id", "");
    EXPECT_NE(doc.text().find("          <object class=\"GtkEntry\"/>\n"), std::string::npos);
}

TEST(UiDocument, PathsFindTheSameNodeAfterReparsing) {
    auto doc = UiDocument::parse(kWindow);
    Node* save = byId(doc, "save");
    const auto path = UiDocument::pathOf(*save);
    auto again = UiDocument::parse(doc.text());
    Node* found = again.atPath(path);
    ASSERT_TRUE(found);
    EXPECT_EQ(UiDocument::objectId(*found), "save");
    EXPECT_EQ(again.atPath({99}), nullptr);
}

TEST(UiDocument, KnowsWhereEachElementIsInTheText) {
    auto doc = UiDocument::parse(kWindow);
    doc.setProperty(*byId(doc, "content"), "spacing", "12"); // spans hold for edited text too
    const std::string text = doc.text();
    const auto spans = doc.spans();
    Node* save = byId(doc, "save");
    const auto [begin, end] = spans.at(save->uid);
    EXPECT_EQ(text.substr(begin, 35), "<object class=\"GtkButton\" id=\"save\"");
    EXPECT_EQ(text.substr(end - 9, 9), "</object>");
    EXPECT_EQ(doc.objectAt(text.find("on_save_clicked")), save);
    EXPECT_EQ(doc.objectAt(text.find("spacing")), byId(doc, "content"));
    EXPECT_EQ(doc.objectAt(0), nullptr);
}

TEST(UiDocument, ReportsWhereTheXmlIsBroken) {
    try {
        UiDocument::parse("<interface>\n  <object class=\"GtkBox\">\n  </interface>\n");
        FAIL() << "no error";
    } catch (const ParseError& e) {
        EXPECT_EQ(e.line, 3);
        EXPECT_NE(std::string(e.what()).find("</object>"), std::string::npos);
    }
    EXPECT_THROW(UiDocument::parse("<interface>\n<object class=\"GtkBox\">"), ParseError);
    EXPECT_THROW(UiDocument::parse("<interface><object class=GtkBox/></interface>"), ParseError);
    EXPECT_THROW(UiDocument::parse("<interface><!-- open"), ParseError);
    EXPECT_THROW(UiDocument::parse("</interface>"), ParseError);
}

TEST(UiPreview, MakesTheDesignSafeToBuildInsideTheIde) {
    auto doc = UiDocument::parse(kWindow);
    const Preview p = makePreview(doc, kindOf);
    const std::string& x = p.xml;
    // The window is a box holding its titlebar and then its content, which fills it.
    EXPECT_NE(x.find("<object class=\"GtkBox\" id=\"main_window\"><property name=\"orientation\">vertical</property>"),
              std::string::npos)
        << x;
    EXPECT_EQ(x.find("GtkApplicationWindow"), std::string::npos);
    EXPECT_EQ(x.find("default-width"), std::string::npos);
    EXPECT_LT(x.find("id=\"header\""), x.find("id=\"content\""));
    EXPECT_NE(x.find("<property name=\"vexpand\">true</property></object></child></object></interface>"), std::string::npos);
    // The header bar shows the designed window's title, not the IDE's.
    EXPECT_NE(x.find("<property name=\"title-widget\"><object class=\"GtkLabel\"><property name=\"label\">Demo &amp; more</property>"),
              std::string::npos);
    // No handlers, no shortcuts that could fire in the IDE.
    EXPECT_EQ(x.find("<signal"), std::string::npos);
    EXPECT_EQ(x.find("GtkShortcutController"), std::string::npos);
    EXPECT_EQ(x.find("domain"), std::string::npos);
    // A class this process doesn't have becomes a labelled box that still shows its children.
    EXPECT_NE(x.find("<object class=\"GtkBox\" id=\"status\">"), std::string::npos);
    EXPECT_NE(x.find("<property name=\"label\">AdwStatusPage</property>"), std::string::npos);
    EXPECT_NE(x.find("id=\"retry\""), std::string::npos);
    EXPECT_EQ(x.find("Nothing here"), std::string::npos);
    EXPECT_NE(x.find("<property name=\"label\">Hello &lt;b&gt;world&lt;/b&gt;</property>"), std::string::npos);

    // Every object has an id that leads back to its node.
    EXPECT_EQ(p.ids.at("main_window"), doc.topLevelObjects()[0]->uid);
    EXPECT_EQ(p.ids.at("retry"), byId(doc, "retry")->uid);
    int menuButtonUid = 0;
    for (Node* o : doc.objects())
        if (UiDocument::className(*o) == "GtkMenuButton") menuButtonUid = o->uid;
    EXPECT_EQ(p.ids.at("__kevc_" + std::to_string(menuButtonUid)), menuButtonUid);
    EXPECT_EQ(p.ids.at("__kevc_label_" + std::to_string(byId(doc, "status")->uid)), byId(doc, "status")->uid);

    ASSERT_EQ(p.roots.size(), 1u);
    EXPECT_EQ(p.roots[0].id, "main_window");
    EXPECT_TRUE(p.roots[0].window);
    EXPECT_TRUE(p.roots[0].titlebar);
    EXPECT_EQ(p.roots[0].title, "Demo & more");
    EXPECT_EQ(p.roots[0].width, 640);
    EXPECT_EQ(p.roots[0].height, 480);
    ASSERT_EQ(p.actions.size(), 1u);
    EXPECT_EQ(p.actions[0].group, "win");
    EXPECT_EQ(p.actions[0].name, "save");

    // GtkBuilder's own parser must accept it: well-formed, and readable by ours.
    EXPECT_NO_THROW(UiDocument::parse(x));
}

TEST(UiPreview, TemplatesAndSeveralTopLevels) {
    auto doc = UiDocument::parse(R"(<interface>
  <template class="DemoWindow" parent="GtkWindow">
    <property name="title">Templated</property>
    <property name="child">
      <object class="GtkLabel" id="l">
        <property name="label">hi</property>
        <binding name="visible"><lookup name="flag">DemoWindow</lookup></binding>
      </object>
    </property>
  </template>
  <object class="GtkAdjustment" id="adj"><property name="upper">10</property></object>
  <object class="GtkBox" id="spare">
    <child><object class="GtkGestureClick"/></child>
    <child><object class="GtkSpinButton"><property name="adjustment">adj</property></object></child>
    <child><object class="GtkDropDown" id="dd"><property name="model"><object class="MyModel"/></property></object></child>
  </object>
  <object class="GtkWindow" id="other">
    <child><object class="GtkLabel" id="other_label"/></child>
  </object>
</interface>)");
    const Preview p = makePreview(doc, kindOf);
    EXPECT_NE(p.xml.find("<object class=\"GtkBox\" id=\"DemoWindow\">"), std::string::npos) << p.xml;
    EXPECT_EQ(p.xml.find("<template"), std::string::npos);
    EXPECT_EQ(p.xml.find("<binding"), std::string::npos);
    EXPECT_EQ(p.xml.find("GtkGestureClick"), std::string::npos);
    EXPECT_NE(p.xml.find("<object class=\"GtkAdjustment\" id=\"adj\">"), std::string::npos);
    // A placeholder can't stand in for a model: the property is left out.
    EXPECT_NE(p.xml.find("<object class=\"GtkDropDown\" id=\"dd\"></object>"), std::string::npos);
    ASSERT_EQ(p.roots.size(), 3u); // not the adjustment
    EXPECT_EQ(p.roots[0].id, "DemoWindow");
    EXPECT_EQ(p.roots[0].title, "Templated");
    EXPECT_FALSE(p.roots[0].titlebar);
    EXPECT_EQ(p.roots[1].id, "spare");
    EXPECT_FALSE(p.roots[1].window);
    EXPECT_EQ(p.roots[2].id, "other");
    EXPECT_NO_THROW(UiDocument::parse(p.xml));
}

// Every .ui file on this computer reads and writes back unchanged (skipped where there are none).
TEST(UiDocument, RoundTripsTheUiFilesOnThisComputer) {
    namespace fs = std::filesystem;
    int checked = 0;
    std::error_code ec;
    for (fs::recursive_directory_iterator it("/usr/share", fs::directory_options::skip_permission_denied, ec), end;
         it != end && checked < 300; it.increment(ec)) {
        if (ec) break;
        if (it->path().extension() != ".ui" || !it->is_regular_file(ec)) continue;
        std::ifstream in(it->path(), std::ios::binary);
        const std::string text((std::istreambuf_iterator<char>(in)), {});
        if (text.find("<interface") == std::string::npos) continue; // Qt Designer files are .ui too
        try {
            EXPECT_EQ(UiDocument::parse(text).text(), text) << it->path();
            ++checked;
        } catch (const ParseError& e) {
            ADD_FAILURE() << it->path() << ": " << e.what();
        }
    }
    if (checked == 0) GTEST_SKIP() << "no GtkBuilder files in /usr/share";
}
